import{_ as r,C as d,o,c as s,a6 as e,E as i}from"./chunks/framework.BoFLe3f3.js";const b=JSON.parse('{"title":"精通中心：五维能力与实战训练","description":"机制、诊断、设计、运营、安全五个维度的 L1–L5 标准，配套 10 个诊断剧本、14 张架构决策卡、8 个 PR 评审训练、间隔重复与证据作品集。","frontmatter":{"title":"精通中心：五维能力与实战训练","description":"机制、诊断、设计、运营、安全五个维度的 L1–L5 标准，配套 10 个诊断剧本、14 张架构决策卡、8 个 PR 评审训练、间隔重复与证据作品集。"},"headers":[],"relativePath":"mastery.md","filePath":"mastery.md","lastUpdated":1792735573000}'),l={name:"mastery.md"};function n(_,t,p,c,h,m){const a=d("MasteryCenter");return o(),s("div",null,[t[0]||(t[0]=e('<h1 id="精通中心" tabindex="-1">精通中心 <a class="header-anchor" href="#精通中心" aria-label="Permalink to &quot;精通中心&quot;">​</a></h1><p>会写代码不等于能扛生产。这一页把「精通」拆成五个可以分别训练、分别证明的维度：</p><table tabindex="0"><thead><tr><th>维度</th><th>一句话标准</th><th>典型证据</th></tr></thead><tbody><tr><td>⚙️ 机制理解</td><td>能预测运行时行为，而不只是复述 API</td><td>源码深潜、时序图、预测-验证记录</td></tr><tr><td>🩺 故障诊断</td><td>用最小证据收敛到根因</td><td>复现脚本、事故时间线、故障树</td></tr><tr><td>🏗️ 架构设计</td><td>在约束下做可解释的取舍</td><td>ADR、边界图、策略表</td></tr><tr><td>📈 运营治理</td><td>让系统在真实流量下持续可信</td><td>性能预算、回滚演练、SLO</td></tr><tr><td>🛡️ 安全与合规</td><td>默认不信任，最小权限，可验证</td><td>威胁模型、越权清单、安全回归</td></tr></tbody></table><p>每一级都要求「可观察信号 + 可提交物」，避免把「读过文档」当成能力。下面的训练台会把你的自评、练习记录、复习进度与作品集保存在本机，不上传任何数据。</p>',4)),i(a),t[1]||(t[1]=e('<h2 id="怎么用这一页" tabindex="-1">怎么用这一页 <a class="header-anchor" href="#怎么用这一页" aria-label="Permalink to &quot;怎么用这一页&quot;">​</a></h2><ol><li><strong>先自评</strong>：在「能力雷达」里给五个维度各选一个等级，不要选「应该达到」的等级，选「现在能拿出证据」的等级。</li><li><strong>做诊断</strong>：每次只打开一个剧本，先只看症状与证据，写下自己的假设树，再展开对照。重点是训练收敛过程，不是背答案。</li><li><strong>做决策</strong>：架构决策卡先自己选，再看推荐结论。把「什么条件下我会推翻它」写进备注。</li><li><strong>练评审</strong>：PR 评审先估自己能看到几个问题，再看完整结论；连续三次低分说明需要回到对应章节。</li><li><strong>间隔复习</strong>：每天只清空到期卡片，不要一次性刷完；评分要诚实，「简单」只留给能立刻说出判据的卡片。</li><li><strong>补证据</strong>：作品集里的每条都对应一个可提交物。没有交付物，就不算到了那一级。</li></ol><h2 id="与正文的关系" tabindex="-1">与正文的关系 <a class="header-anchor" href="#与正文的关系" aria-label="Permalink to &quot;与正文的关系&quot;">​</a></h2><p>精通中心不重复正文，而是把正文里的机制、实验与深潜组织成「可训练、可验证」的任务：</p><ul><li>机制维度的证据来自 <a href="/nextjs-tutorial-site/deep-dives/">源码深潜</a> 与各章「源码内幕」；</li><li>诊断维度对应 7 个 <code>debug-*</code> 实验与 <a href="/nextjs-tutorial-site/troubleshooting">排障图谱</a>；</li><li>设计维度对应每章的取舍与 <a href="/nextjs-tutorial-site/roadmap">学习路线图</a>；</li><li>运营与安全维度对应第 11–13 章与综合实战。</li></ul><div class="tip custom-block"><p class="custom-block-title">建议节奏</p><p>每周完成 1 个诊断剧本 + 1 张决策卡 + 1 次 PR 评审，并把到期卡片清空。四周后回来看雷达，等级应该由证据推动，而不是由心情推动。</p></div>',6))])}const g=r(l,[["render",n]]);export{b as __pageData,g as default};
